#!/bin/bash
# RM2（MU_TORSION 0.02）の確かめ: 5 回跳び（JUMP_REPEAT 4、T 20、180° を狙う）RM2x5、種 27182 の 3 回跳び RM2s2、STANCE_TRUNK_YAW なし RM2ns。あわせて前への連続の基準 R10C に MU_TORSION 0.02（R10CM、3 回跳び）。N=48、種 31415（RM2s2 を除く）、j49。
D=/home/takara/work/dp/articara/log/claude_g1jump_20261021; B=$D/g1_flight_probe_j49
X='"JUMP_ABORT":"1","JUMP_PUSH_R":"0.3","QD_CLAMP":"40","DIAG_TD":"1","FLIGHT_FEET_FLAT":"1","DIAG_HX":"1","RELEASE_FIRST_OFF":"1","WBCW_CONTACT_REST":"0.1","WBCW_TRUNK_LAND":"0.03","FALL_TILT":"1.5","LAND_REF_FOLLOW":"2","AIR_ABORT_T":"0.08"'
H=',"FLIGHT_FEET_CAPTURE_T":"0.06","KP_FLIGHT_FEET":"1000","KD_FLIGHT_FEET":"63","WBCW_TRUNK_PUSH":"0.003","WBCW_MOMENTUM":"10","WBCW_CONTACT":"100","WBCW_TRUNK_LAND_VZ":"0","JUMP_H_NAT":"1","WBCW_CONTACT_REST_LAUNCH":"1","FLIGHT_FEET_CAPTURE":"0.55","FLIGHT_TRUNK":"0","FLIGHT_FEET_W":"10","WBCW_MOMENTUM_PUSH":"1","FLIGHT_FEET_YAW":"1"'
RW=',"T":"13","JUMP_REPEAT":"2","WBCW_TRUNK_LAND_T":"1.0","JUMP_REPEAT_SOFT_CROUCH":"1","JUMP_REPEAT_RECENTRE":"1","FLIGHT_FEET_WIDTH":"0.236","CROUCH_TAB":"1.0:0.12,1.5:0.18","JUMP_REPEAT_HEADING":"1"'
TU=',"JUMP_TURN_HZ":"2","FLIGHT_FEET_TURN":"1","KP_FLIGHT_FEET_ROT":"2000","KD_FLIGHT_FEET_ROT":"89"'
F3=',"JUMP_VX_TAB":"1.0:0.3,1.5:0.36,2.0:0.48","JUMP_LEAN_TAB":"1.0:0,1.5:0.0135,2.0:0.018"'
F5=',"JUMP_VX_TAB":"1.0:0.5,1.5:0.6,2.0:0.8","JUMP_LEAN_TAB":"1.0:0,1.5:0.0225,2.0:0.03"'
cd $D
run() { TAG=$1 SEED=$2 BIN=$B CONDS=$3 N=48 W=4 EXTRA="{$X$H$RW$4}" python3 jrand.py; }
run RM2x5 31415 1.5,2.0 ',"JUMP_VX_TAB":"1.0:0.10,1.5:0.12,2.0:0.48","JUMP_LEAN_TAB":"1.0:0,1.5:0.0045,2.0:0.018","STANCE_TRUNK_YAW":"10"'"$TU"',"MU_TORSION":"0.02","T":"20","JUMP_REPEAT":"4"' &
run RM2s2 27182 1.5,2.0 ',"JUMP_VX_TAB":"1.0:0.10,1.5:0.12,2.0:0.48","JUMP_LEAN_TAB":"1.0:0,1.5:0.0045,2.0:0.018","STANCE_TRUNK_YAW":"10"'"$TU"',"MU_TORSION":"0.02"' &
run RM2ns 31415 1.5,2.0 ',"JUMP_VX_TAB":"1.0:0.10,1.5:0.12,2.0:0.48","JUMP_LEAN_TAB":"1.0:0,1.5:0.0045,2.0:0.018"'"$TU"',"MU_TORSION":"0.02"' &
run R10CM 31415 1.0,1.5,2.0 ',"JUMP_VX_TAB":"1.0:1.0,1.5:1.2,2.0:1.6","JUMP_LEAN_TAB":"1.0:0,1.5:0.045,2.0:0.06","JUMP_REPEAT_HEADING":"0","MU_TORSION":"0.02"' &
wait
python3 rtsumm.py RM2x5; python3 rtsumm.py RM2s2; python3 rtsumm.py RM2 RM2ns; python3 rtfail.py RM2x5 RM2s2 RM2ns
python3 rsumm.py P3C12 R10CM | grep v1.0; python3 rsumm.py R10W R10CM | grep -v v1.0
echo "#### JT15_DONE"
